import { useId } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

export function FocusProgress({ label, elapsedMinutes, totalMinutes }: FocusProgressProps) {
  const labelId = useId();

  const total = Number.isFinite(totalMinutes) && totalMinutes > 0 ? Math.round(totalMinutes) : 0;
  const elapsed = Number.isFinite(elapsedMinutes)
    ? Math.min(Math.max(Math.round(elapsedMinutes), 0), total)
    : 0;
  const remaining = total - elapsed;
  const percent = total === 0 ? 0 : (elapsed / total) * 100;

  return (
    <div className="focus-progress">
      <div className="focus-progress-header">
        <span id={labelId} className="focus-progress-label">
          {label}
        </span>
        <span className="focus-progress-meta" aria-hidden="true">
          <span>
            {elapsed} / {total} min
          </span>
          <span className="focus-progress-remaining">{remaining} min left</span>
        </span>
      </div>
      <div
        role="progressbar"
        tabIndex={0}
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={total}
        aria-valuenow={elapsed}
        aria-valuetext={`${elapsed} of ${total} minutes elapsed, ${remaining} remaining`}
        className="focus-progress-track"
      >
        <div className="focus-progress-fill" style={{ width: `${percent}%` }} />
      </div>
    </div>
  );
}
```

