  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 0.75rem;
  font-size: clamp(0.875rem, 0.6vw + 0.5rem, 1.125rem);
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

.focus-progress-remaining {
  color: var(--muted);
}

.focus-progress-track {
  position: relative;
  height: clamp(0.5rem, 0.8vh, 0.875rem);
  border-radius: 999px;
  background: var(--axon-ahead);
  overflow: hidden;
}

.focus-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--myelin);
  transition: width 400ms ease;
}

